export const DICTS = { it, en };

export function resolveLang(pref) {
  if (pref === 'it' || pref === 'en') return pref;
  const nav = (navigator.language || 'it').toLowerCase();
  return nav.startsWith('it') ? 'it' : 'en';
}

export function makeT(lang) {
  const d = DICTS[lang] || it;
  return (key, vars) => {
    let s = d[key] ?? it[key] ?? key;
    if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? `{${k}}`));
    return s;
  };
}
